For any given bandwidth $h >0$, \df{in the stochastic setting,} \smoothpe (\pref{alg:ZPE-body}) with
parameter $h$ achieves
\begin{align*}
\Reg(T,\Pi_h)
\leq O\rbr{\inf_{\epsilon_0 > 0}
\cbr{ T\epsilon_0 + \theta_h(\epsilon_0)\;\log(|\Pi|\df{T})\;\log(1/\epsilon_0) } }.
\end{align*}

Fix any bandwidth $h > 0$, \df{in the stochastic setting,} \smoothpe with parameter $h$ achieves
\begin{align*}
\Reg(T,\Pi_h) \leq \tilde{O} \rbr{\sqrt{\nicefrac{T}{h} \log|\Pi| }}.
\end{align*}

Consider the adversarial setting.
For each $\beta \in [0,1]$,
\corralexpf (with parameter $\beta$) is Lipschitz-adaptive with
\begin{align*}
\Reg(T,\Pi) \leq \otil
    \rbr{ T^{1-a}\;L^b\; \rbr{\log|\Pi|}^a},\;
\text{where}\quad
a = \frac{\beta}{1+2\beta}
\;\text{and}\;
b = \frac{\beta}{1+\beta}.
\end{align*}

Algorithm \corralexpf with parameter $\beta\in [0,1]$ guarantees the following for each $i\in[M]$:
\begin{align*}
\Reg(T,\Pi_{K_i}) \leq \order
\rbr{ T^{\frac{1}{1+\beta}}\;
    \rbr{\kappa_i  \log(|\Pi|M)}^{\frac{\beta}{1+\beta}}}
\cdot
\rbr{\min\cbr{M, \log \frac{\kappa_{\max}}{\kappa_\star}}}^{\frac{1}{1+\beta}}\; \rbr{\frac{\kappa_i}{\kappa_\star}}^{\frac{\beta^2}{1+\beta}} .
\end{align*}

Consider the stochastic setting under \pref{assum:uniform}. Recall policy-zooming coefficient $\psi_L(\eps_0)$ and zooming dimension $z$ (with constant $\gamma)$, as defined in
\eqref{eq:policy-zooming-coeff} and \eqref{eq:zooming-dim-defn}. In this setting,
\zpelip with parameter $L$ achieves
\begin{align*}
\Reg(T,\Pi)
&\leq O\rbr{\inf_{\eps_0 > 0} TL\eps_0 +
\frac{\alpha\cdot \psi_L(\eps_0)}{L} \cdot \log(|\Pi|\df{T})\log(1/\eps_0)} \\
&\leq \tilde{O}
    \rbr{ T^{1-a}\; L^{1-2a}\;
        \rbr{\gamma \log |\Pi|}^a },\;
    \text{where}\quad a = \tfrac{1}{2+z}.

&\leq \tilde{O}
    \rbr{ T^{1-a}\; L^{1-2a}\;
        \rbr{\gamma \log |\Pi|}^a },\;
    \text{where}\quad a = \tfrac{1}{2+z}.
